UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"Severity Grade","body":"**Grade the envenomation:**\n\n| Grade | Local Signs | Systemic | Labs |\n|-------|------------|----------|------|\n| **Dry (0)** | Fang marks only | None | Normal |\n| **Mild (1)** | Local edema, not crossing joint | Minimal | Normal |\n| **Moderate (2)** | Entire extremity | Nausea, paresthesias | Minor abnl |\n| **Severe (3)** | Rapid progression, necrosis | Hypotension, AMS | Severe abnl |\n\n**Copperhead bites** are often mild — many do NOT require antivenom.\n\n**Rattlesnake bites** more likely to cause coagulopathy and systemic toxicity.\n\n**Severity grade does not determine the initial CroFab dose.** Rapid progression or coagulopathy alone does not justify 8-12 vials. Use 4-6 vials initially when antivenom is indicated; reserve 8-12 for immediately life-threatening venom effects such as shock or serious active bleeding. [7]\n\nWhat is the severity grade?","citation":[1,3,7],"options":[{"label":"Dry Bite (Grade 0)","description":"Fang marks only, no swelling or symptoms","next":"snake-dry-bite"},{"label":"Mild (Grade 1)","description":"Local edema only, no systemic symptoms","next":"snake-mild"},{"label":"Moderate (Grade 2)","description":"Extremity involvement, minor systemic symptoms","next":"snake-moderate"},{"label":"Severe (Grade 3)","description":"Rapid progression, hypotension, coagulopathy","next":"snake-severe","urgency":"critical"}],"summary":"Grade 0-3: dry (fang marks only) to severe (rapid progression, hypotension, coagulopathy); copperheads often mild"}'::jsonb
WHERE id = 'snake-pit-severity-grade' AND tree_id = 'snake-envenomation';

-- Node: snake-severe (4 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Severe Envenomation","body":"**Severe envenomation — aggressive management:**\n\n**Immediate priorities:**\n1. Airway assessment — early intubation for head/neck bites\n2. Large-bore IV × 2\n3. Aggressive fluid resuscitation\n4. Blood products if active bleeding (see below)\n5. **PROMPT ANTIVENOM**\n\n**Initial antivenom dosing is based on immediate life threats, not severity grade:**\n- CroFab: **4-6 vials** for progressive swelling or coagulopathy without immediately life-threatening effects.\n- Reserve **8-12 vials** for immediately life-threatening venom effects such as **shock or serious active bleeding**. Rapid progression or abnormal coagulation tests alone do not select this higher initial dose.\n- Anavip: **10 vials** initially.\n- Reassess response after infusion; repeat antivenom if initial control is not achieved. Consult Poison Control (1-800-222-1222). [7]\n\n**Coagulopathy management:**\n⚠️ **Treat with ANTIVENOM, not blood products first**\n- FFP/platelets/cryo only for ACTIVE SIGNIFICANT BLEEDING\n- Blood products alone only temporarily correct coagulopathy\n- Antivenom addresses the underlying cause\n\n**Hypotension:**\n- IVF resuscitation\n- Vasopressors if refractory\n\n[Antivenom Calculator](#/calculator/snake-antivenom) [1][3][4]","citation":[1,3,4,7],"next":"snake-antivenom-decision","treatment":{"firstLine":{"drug":"CroFab or Anavip","dose":"CroFab 4-6 vials; 8-12 only for immediately life-threatening effects (e.g., shock or serious active bleeding). Anavip 10 vials","route":"IV","frequency":"Repeat until control achieved","duration":"Until initial control, then maintenance per protocol","notes":"No maximum dose. Treat coagulopathy with antivenom first, not blood products. Blood products only for active significant bleeding."},"alternative":{"drug":"Blood products (for active bleeding only)","dose":"FFP 2-4 units, Platelets 1 apheresis unit, Cryoprecipitate 10 units","route":"IV","frequency":"PRN for active bleeding","duration":"Until bleeding controlled","notes":"Only use WITH antivenom for active significant bleeding. Blood products alone only temporarily correct coagulopathy."},"monitoring":"Continuous hemodynamic monitoring. Serial labs q4-6h. Airway reassessment for head/neck bites. Watch for progression despite treatment."},"calculatorLinks":[{"id":"snake-antivenom","label":"Antivenom Dosing"}],"summary":"CroFab initially 4-6 vials; 8-12 only for immediately life-threatening effects such as shock or serious active bleeding. Anavip 10 vials. Coagulopathy alone does not justify higher initial dosing","safetyLevel":"critical"}'::jsonb
WHERE id = 'snake-severe' AND tree_id = 'snake-envenomation';

-- Node: snake-crofab (4 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"CroFab Administration","body":"**CroFab Dosing Protocol:**\n\n**Reconstitution:**\n1. Reconstitute each vial with 18 mL NS\n2. Mix by continuous manual inversion (1-2/sec)\n3. **DO NOT SHAKE** (causes foaming)\n4. Reconstitution should take < 7 min\n5. Dilute total dose to 250 mL NS\n6. Use within 4 hours\n\n**Initial Dose:**\n- Standard: **4-6 vials** IV\n- **8-12 vials** IV only for **immediately life-threatening venom effects**, such as **shock or serious active bleeding**.\n- Rapid progression or coagulopathy alone: start with **4-6 vials**, regardless of severity grade. Reassess after infusion and repeat antivenom if initial control is not achieved. [7]\n- Pediatric = Adult dose\n\n**Administration:**\n- Start slow: 25-50 mL/hr × 10 min\n- If no reaction: increase to 250 mL/hr\n- Monitor for anaphylaxis\n\n**Maintenance Dosing (Controversial):**\n- 2 vials at 6, 12, and 18 hours post-initial control\n- Consult poison center for guidance\n\n[CroFab/Anavip Calculator](#/calculator/snake-antivenom) [3][4]","citation":[3,4,7],"next":"snake-response-assess","treatment":{"firstLine":{"drug":"CroFab (Crotalidae Polyvalent Immune Fab)","dose":"4-6 vials initially; 8-12 only for immediately life-threatening effects such as shock or serious active bleeding","route":"IV","frequency":"Initial dose, then reassess; maintenance 2 vials at 6, 12, 18h if needed","duration":"Until initial control achieved","notes":"Reconstitute each vial with 18 mL NS, dilute total dose to 250 mL NS. Start infusion at 25-50 mL/hr x 10 min, then increase to 250 mL/hr if no reaction. Pediatric dose = adult dose."},"monitoring":"Monitor for anaphylaxis during infusion. Serial exams q30-60 min post-infusion. Repeat labs at 6, 12, 24 hours. Watch for recurrence phenomenon days 2-7."},"calculatorLinks":[{"id":"snake-antivenom","label":"Antivenom Dosing"}],"summary":"CroFab initially 4-6 vials; 8-12 only for immediately life-threatening effects (shock or serious active bleeding); dilute in 250mL NS; start slow 25-50mL/hr x10min then 250mL/hr; maintenance 2 vials at 6/12/18hr"}'::jsonb
