UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Head/Neck Bite — Airway Management","body":"**Head, face, or neck bites — high airway risk:**\n\n**Early Intubation Considerations:**\n- Progressive facial/oropharyngeal edema\n- Stridor or voice changes\n- Difficulty managing secretions\n- Concern for rapid progression\n\n**Do NOT wait** for respiratory distress — edema may make later intubation impossible.\n\n**Approach:**\n- Early airway assessment\n- Prepare for difficult airway\n- Have surgical airway available\n- Consider early intubation if ANY airway concerns\n\n**Antivenom:**\n- Give aggressively to reduce swelling\n- CroFab initially 4-6 vials when indicated. Reserve 8-12 vials for immediately life-threatening venom effects (e.g., shock, serious active bleeding, or impending airway obstruction), not bite location alone. Obtain urgent toxicology guidance. [7]\n\n**Disposition:**\n- ICU admission\n- Close airway monitoring [1][3]","citation":[1,3,7],"next":"snake-dispo-decision","summary":"Early intubation for progressive facial/oropharyngeal edema — do NOT wait for respiratory distress; prompt antivenom; CroFab 4-6 initially, 8-12 only for immediately life-threatening effects, not bite location alone","safetyLevel":"critical"}'::jsonb
